$docx = 'C:\Users\win\Desktop\Agent Platform\docs\敖钦AI中台总体建设方案.docx'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$zip = [System.IO.Compression.ZipFile]::OpenRead($docx)
try {
  function Read-ZipText($name) {
    $entry = $zip.GetEntry($name)
    if (-not $entry) { return $null }
    $stream = $entry.Open()
    try { $reader = [System.IO.StreamReader]::new($stream, [Text.Encoding]::UTF8); return $reader.ReadToEnd() }
    finally { $reader.Dispose(); $stream.Dispose() }
  }
  [xml]$doc = Read-ZipText 'word/document.xml'
  [xml]$comments = Read-ZipText 'word/comments.xml'
  $ns = [System.Xml.XmlNamespaceManager]::new($doc.NameTable)
  $ns.AddNamespace('w','http://schemas.openxmlformats.org/wordprocessingml/2006/main')
  $ns.AddNamespace('a','http://schemas.openxmlformats.org/drawingml/2006/main')
  $ns.AddNamespace('wp','http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing')
  $commentMap = @{}
  if ($comments -and $comments.DocumentElement) {
    $cns = [System.Xml.XmlNamespaceManager]::new($comments.NameTable)
    $cns.AddNamespace('w','http://schemas.openxmlformats.org/wordprocessingml/2006/main')
    foreach ($c in $comments.SelectNodes('//w:comment', $cns)) {
      $id = $c.GetAttribute('id', 'http://schemas.openxmlformats.org/wordprocessingml/2006/main')
      $txt = (($c.SelectNodes('.//w:t', $cns) | ForEach-Object { $_.'#text' }) -join '') -replace '\s+', ' '
      $commentMap[$id] = $txt.Trim()
    }
  }
  $paras = $doc.SelectNodes('//w:body//w:p', $ns)
  $i = 0
  $hits = @()
  foreach ($p in $paras) {
    $i++
    $full = (($p.SelectNodes('.//w:t', $ns) | ForEach-Object { $_.'#text' }) -join '') -replace '\s+', ' '
    $highlightRuns = @()
    foreach ($r in $p.SelectNodes('.//w:r', $ns)) {
      $h = $r.SelectSingleNode('./w:rPr/w:highlight', $ns)
      $shd = $r.SelectSingleNode('./w:rPr/w:shd', $ns)
      $isYellow = $false
      if ($h) { $val = $h.GetAttribute('val', 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'); if ($val -match 'yellow') { $isYellow = $true } }
      if ($shd) { $fill = $shd.GetAttribute('fill', 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'); if ($fill -match '^(FFFF00|fff000|ffff00)$') { $isYellow = $true } }
      if ($isYellow) { $highlightRuns += (($r.SelectNodes('.//w:t', $ns) | ForEach-Object { $_.'#text' }) -join '') }
    }
    $commentIds = @()
    foreach ($cr in $p.SelectNodes('.//w:commentReference', $ns)) { $commentIds += $cr.GetAttribute('id', 'http://schemas.openxmlformats.org/wordprocessingml/2006/main') }
    $drawingTexts = (($p.SelectNodes('.//a:t', $ns) | ForEach-Object { $_.'#text' }) -join ' | ') -replace '\s+', ' '
    $hasDrawing = [bool]$p.SelectSingleNode('.//w:drawing', $ns)
    if ($highlightRuns.Count -gt 0 -or $commentIds.Count -gt 0 -or $hasDrawing) {
      $hits += [pscustomobject]@{
        para = $i
        text = $full.Trim()
        highlighted = (($highlightRuns -join '') -replace '\s+', ' ').Trim()
        comments = (($commentIds | ForEach-Object { if ($commentMap.ContainsKey($_)) { "[$_] $($commentMap[$_])" } else { "[$_]" } }) -join ' || ')
        hasDrawing = $hasDrawing
        drawingText = $drawingTexts.Trim()
      }
    }
  }
  $media = $zip.Entries | Where-Object { $_.FullName -like 'word/media/*' } | Select-Object FullName, Length
  $summary = [pscustomobject]@{ highlightOrCommentOrDrawingParagraphs = $hits; media = $media }
  $summary | ConvertTo-Json -Depth 5
}
finally { $zip.Dispose() }
'@","workdir":"C:\Users\win\Desktop\Agent Platform","timeout_ms":30000}

